/* ============================================================================
   startup-motion-v53.js — bootstrap real da animação do Ranking Geral
   ----------------------------------------------------------------------------
   Regras desta integração:
   - usa o RGMotion original da animação aprovada, sem reinterpretar a marca;
   - começa em t=0 e força a pintura do primeiro quadro antes de avançar o relógio;
   - reproduz a sequência inteira em 6,4 s, 1x, tema escuro, brilho Intenso (=1);
   - a aplicação carrega em paralelo, mas só aparece quando animação + app estiverem prontos;
   - motion=false explícito na URL significa "não reduzir movimento" e prevalece sobre
     prefers-reduced-motion do SO; motion=true reduz imediatamente;
   - quando não há escolha explícita do app, prefers-reduced-motion continua respeitado;
   - o arquivo é mantido como o ponto único da animação para o cache offline.
   ============================================================================ */
(function(){
  'use strict';

  const BUILD='20260921-v58-dia7-corrigido';
  const splash=document.getElementById('rg-startup');
  const canvas=document.getElementById('rg-startup-canvas');
  const fallback=document.getElementById('rg-startup-fallback');
  const skip=document.getElementById('rg-startup-skip');
  const live=document.getElementById('rg-startup-live');
  if(!splash||!canvas) return;

  const ctx=canvas.getContext('2d',{alpha:true});
  const DURATION=(window.RGMotion&&Number(window.RGMotion.DURATION))||6.4;
  const INTENSE_GLOW=1;
  const motionMedia=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)'):null;
  const image=new Image();
  image.decoding='async';
  try{image.fetchPriority='high';}catch(_){ }
  const factory=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c;};

  let renderer=null;
  let time=0;
  let last=0;
  let raf=0;
  let appReady=false;
  let finished=false;
  let skipped=false;
  let visible=true;
  let animationStarted=false;
  let explicitMotion=null;

  try{
    const raw=new URLSearchParams(window.location.search).get('motion');
    if(raw!==null){
      const v=String(raw).toLowerCase();
      explicitMotion=(v==='true'||v==='on'||v==='1');
    }
  }catch(_){explicitMotion=null;}

  function shouldReduce(){
    // Uma escolha feita dentro do próprio app sempre vence.
    if(window.A11Y&&window.A11Y.estado&&window.A11Y.estado.motion===true) return true;
    if(explicitMotion===false) return false;
    if(explicitMotion===true) return true;
    return !!(motionMedia&&motionMedia.matches);
  }

  function announce(text){
    if(live&&text&&live.textContent!==text) live.textContent=text;
  }

  function setPhase(name){
    splash.dataset.motionPhase=name;
    splash.dataset.motionBuild=BUILD;
  }

  function inertUnderlying(on){
    ['slot-modulo-0','app-shell','a11y-toggle-btn'].forEach(id=>{
      const el=document.getElementById(id); if(!el) return;
      try{el.inert=!!on;}catch(_){
        if(on) el.setAttribute('aria-hidden','true');
        else el.removeAttribute('aria-hidden');
      }
    });
  }

  function fitCanvas(){
    const stage=canvas.parentElement;
    const r=(stage||canvas).getBoundingClientRect();
    if(!r.width||!r.height) return;
    const dpr=Math.min(2,window.devicePixelRatio||1);
    const w=Math.max(1,Math.round(r.width*dpr));
    const h=Math.max(1,Math.round(r.height*dpr));
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
    paint();
  }

  function paint(){
    if(renderer){
      const drawTime=(shouldReduce()||skipped)?DURATION:time;
      renderer.draw(ctx,canvas.width,canvas.height,drawTime,{theme:'dark',glow:INTENSE_GLOW});
      if(fallback) fallback.hidden=true;
    }else{
      ctx.setTransform(1,0,0,1,0,0);
      ctx.clearRect(0,0,canvas.width,canvas.height);
      ctx.fillStyle='#090f15';
      ctx.fillRect(0,0,canvas.width,canvas.height);
      if((shouldReduce()||skipped)&&fallback) fallback.hidden=false;
    }
  }

  function stop(){
    if(raf){cancelAnimationFrame(raf);raf=0;}
  }

  function hide(){
    if(!visible) return;
    visible=false;
    stop();
    setPhase('leaving');
    splash.classList.add('rg-startup-hide');
    splash.setAttribute('aria-hidden','true');
    if(skip) skip.setAttribute('tabindex','-1');
    if(document.body) document.body.removeAttribute('data-startup-visible');
    inertUnderlying(false);
    announce('Ranking Geral pronto.');
    window.setTimeout(()=>setPhase('hidden'),280);
  }

  function maybeFinish(){
    if(!visible) return;
    if((finished||skipped||shouldReduce())&&appReady){
      window.setTimeout(hide,120);
    }
  }

  function tick(now){
    if(!visible||skipped||shouldReduce()||!renderer) return;
    if(last) time=Math.min(DURATION,time+(now-last)/1000);
    last=now;
    paint();
    splash.dataset.motionTime=time.toFixed(3);
    if(time>=DURATION){
      time=DURATION;
      finished=true;
      setPhase('finished');
      paint();
      announce('Animação concluída.');
      maybeFinish();
      return;
    }
    raf=requestAnimationFrame(tick);
  }

  function beginTimeline(){
    if(animationStarted||!renderer||shouldReduce()||skipped) return;
    animationStarted=true;
    time=0;
    last=0;
    setPhase('playing');
    // Duplo RAF: garante que o quadro t=0 tenha oportunidade real de ser composto
    // antes de o relógio da animação avançar. Evita abrir já no logo montado.
    paint();
    requestAnimationFrame(()=>{
      paint();
      requestAnimationFrame(()=>{
        last=0;
        raf=requestAnimationFrame(tick);
      });
    });
  }

  window.RGStartup={
    build:BUILD,
    show:function(text){announce(text||'Carregando…');},
    status:function(text){announce(text||'Carregando…');},
    done:function(text){appReady=true;announce(text||'Painel pronto.');maybeFinish();},
    isVisible:function(){return visible;},
    reduceMotion:function(){explicitMotion=true;skipped=true;time=DURATION;finished=true;stop();paint();maybeFinish();},
    // Diagnóstico sem interferir no app.
    diagnostic:function(){return {build:BUILD,time,appReady,finished,skipped,visible,animationStarted,reduced:shouldReduce(),renderer:!!renderer,phase:splash.dataset.motionPhase||''};}
  };

  setPhase('preparing');
  if(document.body) document.body.setAttribute('data-startup-visible','true');
  document.addEventListener('DOMContentLoaded',()=>inertUnderlying(visible));

  if(skip) skip.addEventListener('click',()=>{
    skipped=true; time=DURATION; finished=true; stop(); paint();
    setPhase('skipped'); announce('Animação pulada.'); maybeFinish();
  });

  document.addEventListener('keydown',e=>{
    if(visible&&e.key==='Escape'&&!e.defaultPrevented){
      skipped=true;time=DURATION;finished=true;stop();paint();setPhase('skipped');maybeFinish();
    }
  });

  if(motionMedia&&motionMedia.addEventListener){
    motionMedia.addEventListener('change',()=>{
      if(explicitMotion===null&&shouldReduce()){
        skipped=true;time=DURATION;finished=true;stop();paint();setPhase('reduced');maybeFinish();
      }
    });
  }

  window.addEventListener('a11y:change',e=>{
    if(e&&e.detail&&typeof e.detail.motion==='boolean') explicitMotion=!!e.detail.motion;
    if(shouldReduce()){
      skipped=true;time=DURATION;finished=true;stop();paint();setPhase('reduced');maybeFinish();
    }
  });

  document.addEventListener('visibilitychange',()=>{
    if(document.hidden) stop();
    else if(visible&&!finished&&!skipped&&!shouldReduce()&&renderer){
      last=0;raf=requestAnimationFrame(tick);
    }
  });

  if(window.ResizeObserver) new ResizeObserver(fitCanvas).observe(canvas.parentElement||canvas);
  else window.addEventListener('resize',fitCanvas,{passive:true});

  image.onload=()=>{
    try{
      setPhase('assembling');
      renderer=window.RGMotion.createRenderer(image,factory);
      time=shouldReduce()?DURATION:0;
      fitCanvas();
      if(shouldReduce()){
        finished=true;setPhase('reduced');paint();maybeFinish();
      }else{
        beginTimeline();
      }
    }catch(err){
      console.error('Falha ao preparar a animação de abertura.',err);
      if(fallback) fallback.hidden=false;
      finished=true;setPhase('fallback');maybeFinish();
    }
  };

  image.onerror=()=>{
    console.error('Falha ao carregar a imagem da animação de abertura.');
    if(fallback) fallback.hidden=false;
    finished=true;setPhase('fallback');maybeFinish();
  };

  // Nome físico exclusivo: não pode ser confundido com imagem antiga por SW pré-v53.
  image.src='data:image/png;base64,';
})();
